<div class="section-heading"><div><span>Secure document vault</span><h2>Documents</h2><p>Upload and organize approved business and application files.</p></div></div>
<form class="portal-card upload-panel" method="post" enctype="multipart/form-data" action="<?=htmlspecialchars(url('/customer/documents/upload'))?>"><?=csrf_field()?><input name="title" placeholder="Document title" required><select name="category"><?php foreach(['personal','gst','pan','company','applications','contracts','invoices','others'] as $cat):?><option value="<?=$cat?>"><?=ucfirst($cat)?></option><?php endforeach;?></select><select name="service_request_id"><option value="">General document</option><?php foreach($applications as $app):?><option value="<?=$app['id']?>"><?=htmlspecialchars($app['application_number'])?></option><?php endforeach;?></select><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png,.webp" required><button class="primary-action">Upload securely</button></form>
<div class="document-grid"><?php foreach($documents as $doc):?><article class="document"><i data-lucide="file-check-2"></i><span><strong><?=htmlspecialchars($doc['title'])?></strong><small><?=htmlspecialchars(ucfirst($doc['category']))?> · <?=number_format($doc['file_size']/1024,0)?> KB</small></span><a href="<?=htmlspecialchars(url('/customer/documents/'.$doc['id'].'/download'))?>" aria-label="Download <?=htmlspecialchars($doc['title'])?>"><i data-lucide="download"></i></a><?php if($doc['source']==='customer'):?><form method="post" action="<?=htmlspecialchars(url('/customer/documents/'.$doc['id'].'/delete'))?>"><?=csrf_field()?><button aria-label="Delete <?=htmlspecialchars($doc['title'])?>"><i data-lucide="trash-2"></i></button></form><?php endif;?></article><?php endforeach;?></div>
